"""Stylesheets for the authentication screen."""
AUTH_DARK_QSS = "\n            * {\n                font-family: \"Segoe UI\", Tahoma, Geneva, Verdana, sans-serif;\n            }\n            QWidget {\n                background-color: #1E1E1E;\n                margin: 0px;\n                padding: 0px;\n            }\n            QLabel#welcome_label {\n                font-size: 22px;\n                font-weight: 700;\n                margin-bottom: 20px;\n                color: #fff;\n                transition: all 0.25s ease;\n            }\n            QLabel#welcome_label:hover {\n                color: #80c0ff;\n                font-size: 26px;\n                text-shadow: 0 0 12px #80c0ffaa;\n            }\n            QLabel#error_label {\n                background-color: #e74c3c;\n                border-radius: 8px;\n                padding: 12px 20px;\n                font-weight: 600;\n                color: white;\n                margin-top: 15px;\n                box-shadow: 0 3px 7px rgba(0,0,0,0.4);\n            }\n            QLineEdit {\n                background-color: #2A2A2A;\n                color: #fff;\n                border: 2px solid #555;\n                border-radius: 14px;\n                padding: 14px 20px;\n                font-size: 17px;\n                selection-background-color: #3f51b5;\n                selection-color: white;\n                transition: border-color 0.3s ease, background-color 0.3s ease;\n            }\n            QLineEdit::placeholder {\n                color: #aaa;\n            }\n            QLineEdit:focus {\n                border-color: #3f51b5;\n                box-shadow: 0 0 6px #3f51b5aa;\n            }\n            QPushButton#login_button {\n                background-color: #3f51b5;\n                color: white;\n                font-weight: 700;\n                border-radius: 18px;\n                padding: 14px 32px;\n                min-width: 110px;\n                min-height: 48px;\n                box-shadow: 0 5px 16px rgba(63,81,181,0.6);\n                transition: background-color 0.3s ease, box-shadow 0.3s ease;\n            }\n            QPushButton#login_button:hover {\n                background-color: #2c387e;\n                box-shadow: 0 8px 28px rgba(44,56,126,0.8);\n            }\n            QPushButton#close_button {\n                background-color: #555;\n                color: #ddd;\n                font-weight: 600;\n                border-radius: 18px;\n                padding: 14px 28px;\n                min-width: 100px;\n                min-height: 48px;\n                box-shadow: none;\n                transition: background-color 0.3s ease;\n            }\n            QPushButton#close_button:hover {\n                background-color: #777;\n            }\n            QLabel[focused=\"true\"] {\n                font-size: 19px;\n                color: #80c0ff;\n                font-weight: 700;\n                text-shadow: 0 0 8px #80c0ffcc;\n                transition: all 0.3s ease;\n            }\n            QLabel {\n                font-weight: 600;\n                min-width: 90px;\n                color: #ddd;\n                transition: all 0.3s ease;\n            }\n        "

